  'legal.collect.h': 'ข้อมูลที่เก็บ',
  'legal.collect': '• เล่นแบบไม่สมัคร: เซฟเกมและการตั้งค่าเก็บในเบราว์เซอร์ของคุณเท่านั้น\n• บัญชีผู้เล่น: อีเมล ชื่อที่ตั้ง และรหัสผ่าน (เก็บแบบเข้ารหัสโดย Supabase) ถ้าเข้าด้วย Google จะได้อีเมลและชื่อจาก Google\n• เซฟบนคลาวด์: ข้อมูลเกมของคุณ เพื่อให้เล่นต่อได้ทุกเครื่อง\n• สถิติการเล่นแบบไม่ระบุตัวตน (ปิดได้ในตั้งค่า): เช่น เริ่มเกม ผ่านบท และเวลาเล่นโดยประมาณ\n• อันดับออนไลน์ (เฉพาะเมื่อคุณเลือกเข้าร่วม): ชื่อที่แสดง ชื่อศูนย์ คะแนน และผังอาคาร ซึ่งทุกคนมองเห็น\n• ความคิดเห็นที่ส่งมา: ข้อความ ช่องทางติดต่อที่ใส่เอง และข้อมูลเกมเล็กน้อย',
  'legal.use.h': 'ใช้ข้อมูลทำอะไร',
  'legal.use': 'ใช้เพื่อให้เล่นเกมได้ เก็บเซฟ แสดงอันดับ แก้ปัญหา และปรับปรุงเกมเท่านั้น ไม่มีโฆษณา ไม่ขายหรือให้ข้อมูลแก่ผู้อื่นเพื่อการตลาด',
  'legal.share.h': 'ผู้ให้บริการที่เกี่ยวข้อง',
