  'faq.staff.tip2': 'กะดึกต้องมีคนอย่างน้อย 1 คน ผู้พักติดเตียง ให้อาหารทางสาย และดูแลทางเดินหายใจต้องใช้ CG ตอนดึกมากขึ้น ผู้พักเจาะคอต้องมี RN ตอนดึกด้วย',
  'faq.staff.tip3': 'คร่าวๆ คือ CG 1 คนต่อผู้พัก 3–4 คนในกะกลางวัน PN ช่วยงานพยาบาลได้ เพิ่ม 1 คนทุก 10 ผู้พัก',
  'faq.staff.tip4': 'พนักงาน 1 คนลงได้ 2 กะ (สูงสุด 16 ชม.) แต่จะเหนื่อยเร็ว งานช้าลง และขวัญกำลังใจตก',
  'faq.staff.tip5': 'เปิด 🤖 อัตโนมัติ > "จ้างพนักงานตามจำเป็นและจัดเวร" ให้ระบบจ้างและจัดเวรตามตัวเลขนี้ให้เองได้',
