  'legal.updated': 'Privacy policy and terms of use (last updated October 2026)',
  'legal.about.h': 'About the game',
  'legal.about': 'Healthcare Empire is a care-home management game. All characters, prices and numbers are fictional, for fun. It holds no real patient data and gives no medical or treatment advice.',
  'legal.collect.h': 'What we collect',
  'legal.collect': '• Playing as a guest: saves and settings stay in your browser only\n• Accounts: email, your chosen name and password (stored hashed by Supabase); with Google sign-in, your email and name from Google\n• Cloud saves: your game, so you can carry on from any device\n• Anonymous play statistics (can be switched off in Settings): e.g. games started, chapters passed, rough play time\n• Online ranking (only if you opt in): display name, home name, scores and building layout, visible to everyone\n• Feedback you send: your message, any contact you add, and a little game context',
  'legal.use.h': 'How we use it',
  'legal.use': 'Only to run the game, keep your saves, show the ranking, fix problems and improve the game. No ads; your data is never sold or shared for marketing.',
  'legal.share.h': 'Services involved',
  'legal.share': 'Supabase (database and accounts), Cloudflare Pages and GitHub Pages (hosting, which may keep ordinary access logs) and Google (only with Google sign-in). Support channels such as Ko-fi or PromptPay are third-party services under their own policies.',
  'legal.keep.h': 'Keeping and deleting',
  'legal.keep': 'Account data and saves are kept until you ask for deletion. Leave the ranking any time by unticking it on the Ranking tab; delete saves from the Save window.',
  'legal.rights.h': 'Your rights (Thai PDPA)',
  'legal.rights': 'You can ask to see, correct or delete your data, or withdraw consent: contact {email}, or use the Feedback tab. You may also complain to Thailand\'s Personal Data Protection Committee.',
  'legal.no_email': 'the in-game Feedback tab',
  'legal.kids.h': 'Young players',
  'legal.kids': 'The game suits all ages. Minors should have a parent\'s consent before creating an account, or can play as a guest.',
  'legal.terms.h': 'Terms of use',
  'legal.terms': '• The game is free and provided as is; it may change, and rankings may be reset\n• No offensive or abusive names or messages and no cheating; the creator may remove ranking rows or messages that break this\n• Supporting the creator is voluntary and changes nothing in the game',
  'legal.changes.h': 'Changes',
  'legal.changes': 'Changes to this policy will be announced in the game\'s news.',
