  'faq.staff.q': 'How many RNs and caregivers for how many residents?',
  'faq.staff.intro': 'It depends on your residents\' groups and care levels. The Roster page works it out from your real residents every time (the have/need numbers in each cell). This table is a guide for a typical mix (general, stroke rehab, bedridden).',
  'faq.staff.residents': 'Residents',
  'faq.staff.n': '{n}',
  'faq.staff.legend': 'Numbers are morning / afternoon / night · PT and OT work mornings · RN = registered nurse, PN = practical nurse, CG = caregiver',
  'faq.staff.tip1': 'Morning and afternoon always need at least 1 RN (shift lead), and an RN writes the care plan for each new resident.',
  'faq.staff.tip2': 'Nights need at least one person. Bedridden, tube-feeding and airway residents need more caregivers at night; airway residents need an RN at night too.',
  'faq.staff.tip3': 'Rule of thumb: 1 caregiver per 3–4 residents on day shifts; PNs help with nursing work, about 1 per 10 residents.',
  'faq.staff.tip4': 'One person can work 2 shifts (16 h max) but tires fast, works slower and loses morale.',
  'faq.staff.tip5': 'Turn on 🤖 Auto > "Hire as needed and roster" and the assistant hires and fills shifts to these numbers for you.',
  'faq.money.q': 'When does the money come in?',
  'faq.money.admit': 'On admission: an invoice for room & care for the rest of that month (by the day). The family pays within {a}–{b} days.',
  'faq.money.monthly': 'Day 1 of every game month (day 1, 31, 61 ...): a full month\'s invoice for every resident, paid within {a}–{b} days. With an accounting office and an accountant, it is collected the same day.',
  'faq.money.services': 'Extra services as they are done (therapy {therapy} a session, activity {activity}, special services {special}) are added to next month\'s invoice.',
  'faq.money.leave': 'A resident leaving mid-month gets the unused days refunded, and a final invoice for services owed.',
  'faq.money.costs': 'Costs come off every midnight: wages, food and upkeep (and supplies without a supply room), so cash falls daily and jumps when families pay.',
  'faq.money.fees': 'Monthly room & care (standard price): level 1 {l1} · level 2 {l2} · level 3 {l3} · level 4 {l4}, plus specialised programme fees; value price -10%, premium +20% (fictional).',
  'faq.money.tip': 'Tip: admit residents as early as you can: empty beds earn nothing while wages are paid daily. Watch "cash covers N days" on the Finance page and borrow if it gets short.',
