  'stock.guide.use': 'Each care task takes its supplies when it starts. The bar under each item shows how many days it lasts. When something runs out, that care cannot start and quality drops.',
  'stock.guide.auto': 'Keep "Auto reorder" on: it tops up below the reorder point and sends an express order when work in the next 4 hours would go without.',
  'stock.guide.order': 'Order yourself three ways: standard (tomorrow morning), wholesale (15% cheaper, 3 days) and express (1 hour, 50% dearer). The earliest-expiring stock is used first, so do not hoard until it expires.',
  'stock.guide.shelves': 'Shelf space is limited; when it is full you cannot order more. Build a storage room (60 packs a rack) as the home grows.',
