  'auto.events': 'Answer events and staff requests',
  'auto.events.desc': 'Picks a sensible answer at once without pausing: accepts a staff pay request, welcomes families, takes referrals for the beds you have',
  'auto.admit': 'Admit residents',
  'auto.admit.desc': 'Fills each fitting free bed from the waiting list (urgent referrals first), and the stroke unit too',
  'auto.carePlan': 'Write care plans',
  'auto.carePlan.desc': 'Every resident without a care plan gets one straight away (needs an RN on the staff)',
  'auto.staff': 'Hire as needed and roster',
  'auto.staff.desc': 'Fills roster gaps with staff who have no shift yet, or hires an applicant (never into debt, never dismisses anyone)',
  'auto.build': 'Build ready-made rooms',
  'auto.build.desc': 'At most one room a day, at 08:00: basic rooms still missing (ward, nursing station, staff room, therapy), another 10-bed ward when every bed is taken and 3+ families wait, a villa for waiting premium families; and by chapter: the specialised ward fittings, 30 beds and the RN team (chapter 2), an accounting office and accountant at 30 beds (from chapter 2), the clinic and stroke unit (chapter 6). Placed next to a corridor near the entrance, only with running costs plus a reserve to spare',
