  'auto.estate.desc': 'From chapter 3: villas for premium families and a garden up to full appeal; when the lot is full it buys the next plot and runs a corridor into it',
  'auto.homecare': 'Home Care',
  'auto.homecare.desc': 'From chapter 4: opens the Home Care centre, adds a van for every four clients and takes new clients the vans can serve (visit staff are rostered by the hire-and-roster switch)',
  'auto.training': 'Send staff to training',
  'auto.training.desc': 'From chapter 5: builds the training room, sends free staff for certificates up to the target, and prepares people for placements that need one (hiring if nobody is free)',
  'auto.placements': 'Place staff with partners',
  'auto.placements.desc': 'From chapter 5: accepts offers from factories, clinics and partner organisations with a suitable person, soonest expiry first, up to 4 contracts at once',
  'auto.branches': 'Run branches',
