  'auto.pricing.desc': 'Every morning at 06:00: value prices while over 25% of beds are free (more enquiries); premium when the home is full, 6+ families wait, satisfaction is 75+, reputation 60+ and the chapter\'s resident and programme targets are met; otherwise standard. Bills already issued keep their price',
  'auto.garden': 'Garden and decor from chapter 1',
