  'auto.staffCare': 'Look after tired or unhappy staff',
  'auto.staffCare.desc': 'Every morning at 05:00: anyone on a double shift with energy under 30 or morale under 50 gets the second shift off (the hire switch finds cover), and a home without a staff room gets one; at 10:00, town outings: coffee when average morale is under 60, cake when residents\' happiness is under 55, the (free) park under 80',
